import Foundation

/// Generated by sync-dotfiles.py from the exact portable files shipped with this build.
/// A broken reference is a packaging error, never a reason to invent different defaults.
public struct ReferenceProfile: Decodable {
    public let repository: String
    public let revision: String
    public let files: [String: String]
    public let layout: WorkspaceConfiguration
    public let karabinerShortcuts: [ManagedShortcut]

    public static let bundled: ReferenceProfile = {
        guard let url = Bundle.main.url(forResource: "ReferenceProfile", withExtension: "json")
                ?? Bundle.module.url(forResource: "ReferenceProfile", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let reference = try? JSONDecoder().decode(ReferenceProfile.self, from: data) else {
            preconditionFailure("Missing or invalid bundled reference profile. Run scripts/sync-dotfiles.py before packaging.")
        }
        return reference
    }()
}
